"""Render the tabular styles used by the five manuscript exporters."""

import re

HEADERS = {
    "historical": "% Generated by results_tables.py; edit the export specification, not this file.",
    "development": "% Generated by d4_development.py; edit the exporter, not this file.",
    "components": "% Generated by replication_results.py; edit the exporter.",
    "block": "% Generated by block_results.py.",
}


def add_table(outputs, family, name, title, columns, rows, caption, align, *, groups="", padding=5):
    if any(len(row) != len(columns) for row in rows):
        raise ValueError(f"Ragged table {name}")
    center = "\\centering\n\\small"
    stretch = "1.08"
    if family == "block":
        center, stretch = r"\centering\small", "1.06"
        caption = re.sub(r"([a-z])(?=\d)", r"\1 ", caption)
        caption = caption.replace("Gemma4", "Gemma 4").replace("by100", "by 100")
    if title:
        caption = rf"\textbf{{{title}}} {caption}"
    body = "\n".join(" & ".join(row) + r" \\" for row in rows)
    lines = [
        HEADERS[family],
        r"\begin{table*}[t]",
        center,
        rf"\setlength{{\tabcolsep}}{{{padding}pt}}",
        rf"\renewcommand{{\arraystretch}}{{{stretch}}}",
        rf"\begin{{tabular}}{{@{{}}{align}@{{}}}}",
        r"\toprule",
        groups + " & ".join(columns) + r" \\",
        r"\midrule",
        body,
        r"\bottomrule",
        r"\end{tabular}",
        rf"\caption{{{caption}}}",
        rf"\label{{tab:{name}}}",
        r"\end{table*}",
    ]
    outputs[f"tables/{name}.tex"] = "\n".join(lines) + "\n"
